package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0) // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var TempRecData TempRec

var tempRecords []string
var tempIdx int

func truncateToS9V99(d decimal.Decimal) decimal.Decimal {
	scaled := d.Shift(2).Truncate(0).IntPart()
	neg := scaled < 0
	var abs int64
	if neg {
		abs = -scaled
	} else {
		abs = scaled
	}
	mod := abs % 100000
	if neg {
		mod = -mod
	}
	return decimal.New(mod, -2)
}

func formatIntZZ9(intPart int64) string {
	s := fmt.Sprintf("%03d", intPart)
	b := []byte(s)
	for i := 0; i < 2; i++ {
		if b[i] == '0' && (i == 0 || b[i-1] == ' ') {
			b[i] = ' '
		} else {
			break
		}
	}
	return string(b)
}

func formatZZ9_9(d decimal.Decimal) string {
	t := d.Truncate(1)
	scaled := t.Shift(1).Truncate(0).IntPart()
	var abs int64
	if scaled < 0 {
		abs = -scaled
	} else {
		abs = scaled
	}
	intPart := (abs / 10) % 1000
	frac := abs % 10
	return formatIntZZ9(intPart) + "." + fmt.Sprintf("%01d", frac)
}

func formatMinusZZ9_99(d decimal.Decimal) string {
	t := d.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	neg := scaled < 0
	var abs int64
	if neg {
		abs = -scaled
	} else {
		abs = scaled
	}
	intPart := (abs / 100) % 1000
	frac := abs % 100
	sign := byte(' ')
	if neg {
		sign = byte('-')
	}
	return string([]byte{sign}) + formatIntZZ9(intPart) + "." + fmt.Sprintf("%02d", frac)
}

func ReadPara() {
	if tempIdx >= len(tempRecords) {
		WsEofFlag = "Y"
		return
	}
	line := tempRecords[tempIdx]
	tempIdx++
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	TempRecData.TcSensor = line[0:4]
	fStr := line[4:8]
	var n int64 = 0
	for i := 0; i < 4; i++ {
		c := fStr[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else {
			n = n * 10
		}
	}
	TempRecData.TcF = decimal.New(n, -1)
}

func ProcessPara() {
	diff := TempRecData.TcF.Sub(decimal.NewFromInt(32))
	prod := diff.Mul(decimal.NewFromInt(5))
	quot := prod.Div(decimal.NewFromInt(9))
	rounded := quot.Round(2)
	WsC = truncateToS9V99(rounded)
	if WsC.Cmp(decimal.NewFromInt(0)) < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(TempRecData.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Printf("%s %sF %sC\n", TempRecData.TcSensor, WsFEd, WsCEd)
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	tempRecords = nil
	tempIdx = 0
	for scanner.Scan() {
		tempRecords = append(tempRecords, scanner.Text())
	}
	if serr := scanner.Err(); serr != nil {
		fmt.Fprintln(os.Stderr, serr)
		f.Close()
		os.Exit(1)
	}
	f.Close()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	fmt.Printf("READINGS: %02d BELOW ZERO: %02d\n", WsCount, WsFreeze)
}

func main() {
	MainPara()
}
